import{_ as s,l as o,o as e,c as l,v as t,p as n,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"IPsec 与 IKE","description":"","frontmatter":{"title":"IPsec 与 IKE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipsec-ike.md","filePath":"cs/ipsec-ike.md","lastUpdated":1789023840000}'),P={name:"cs/ipsec-ike.md"};function S(E,a,h,A,I,u){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ipsec-与-ike" tabindex="-1">IPsec 与 IKE <a class="header-anchor" href="#ipsec-与-ike" aria-label="Permalink to &quot;IPsec 与 IKE&quot;">​</a></h1><div class="epigraph"><p>IPsec 把 AEAD 推到 IP 层：SPD 决定哪些流要保护，SAD 里是密钥与 SPI。IKE 负责协商与认证，失败时看起来像「VPN 连不上」，其实是身份与选择器没对齐。</p><footer>—— RFC 4301；RFC 7296 IKEv2；Kent and Seo</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ssh-keys-auth">SSH</a>保护一条交互会话。缺口是<strong>网段之间的策略</strong>：整网段或整主机的 IP 流。主干网络课不重写；本课收 SPD/SAD 与 IKEv2 的合同。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>应用各自 TLS 会漏掉非 TLS 流。IPsec：传输模式对主机，隧道模式对外网关。IKE 用 DH 与身份（PSK 或证书）建 SA。缺口是选择器过宽（所有端口一套 SA）与 PSK 共享——不是再讲 ESP 头字段百科。</p><h3 id="nat-与-udp-封装" tabindex="-1">NAT 与 UDP 封装 <a class="header-anchor" href="#nat-与-udp-封装" aria-label="Permalink to &quot;NAT 与 UDP 封装&quot;">​</a></h3><p>ESP 遇 NAT 常走 UDP。封装不改变「要认证对端」这一条。</p><p><span class="marginnote">RFC 4301 架构。IKEv2 简化 IKEv1 的多轮。本课不给破 SA 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：IKE 认证→子 SA→ESP 处理匹配 SPD 的包。对照 TLS：端点是应用 vs 主机/网关。指出策略冲突（旁路）比算法选择更常出事。</p>',12)),(e(),n(p,null,{default:i(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IKE%5B%22IKEv2%20%E8%AE%A4%E8%AF%81%E4%B8%8E%20DH%22%5D%20--%3E%20SA%5B%22SAD%20%E4%B8%AD%E7%9A%84%20SA%22%5D%0A%20%20SPD%5B%22SPD%20%E9%80%89%E6%8B%A9%E5%99%A8%22%5D%20--%3E%20ESP%5B%22ESP%20AEAD%22%5D%0A%20%20SA%20--%3E%20ESP%0A%20%20ESP%20--%3E%20IP%5B%22%E5%8F%97%E4%BF%9D%E6%8A%A4%20IP%20%E6%B5%81%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>网络层保密把中间路径变成密文，但不自动给应用身份。网关 VPN 常把所有远程用户变成一个内网源——零信任课会拆这条。下一课 WireGuard：刻意变小的另一合同。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 IKEv1 模式。WireGuard 下一课用 Noise 与静态钥把协商收短。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SSH 管登录；IPsec 管 IP 流策略。</li><li>IKE 建 SA；SPD 决定什么必须进 ESP。</li><li>PSK 与过宽选择器是常见合同松弛。</li><li>下一课 WireGuard。</li><li>出处：RFC 4301；RFC 7296；Kent and Seo。</li></ul>',8))])}const m=s(P,[["render",S]]);export{D as __pageData,m as default};
